content:
.page {
  display: grid;
  place-items: center;
  min-height: 72svh;
  padding: clamp(28px, 6vw, 80px) 20px;
  background: #fafbf8;
}
.card {
  width: 100%;
  max-width: 1040px;
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  align-items: center;
  overflow: hidden;
  border: 1px solid #e3e8df;
  border-radius: 28px;
  background: #fff;
  box-shadow: 0 20px 70px -45px #173b2740;
}
.art {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 460px;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(ellipse at 30% 35%, #fcfdf8, #edf3e8);
}
.number { z-index: 1; color: #254936; font-size: clamp(100px, 12vw, 156px); font-weight: 500; letter-spacing: -.09em; line-height: 1; padding-right: .09em; }
.orbit { position: absolute; width: 310px; height: 310px; border: 1px solid #cfdcc9; border-radius: 50%; transform: rotate(-28deg) scaleY(.72); }
.orbit::after { content: ""; position: absolute; inset: -30px; border: 1px solid #dce6d7; border-radius: inherit; }
.spark { position: absolute; z-index: 2; right: 16%; top: 25%; display: grid; place-items: center; width: 46px; height: 46px; border: 5px solid #f0f5eb; border-radius: 50%; color: #173c28; background: #bcdf9b; }
.spark svg { width: 23px; height: 23px; }
.content { padding: clamp(28px, 5vw, 64px); }
.eyebrow { display: flex; align-items: center; gap: 12px; margin: 0 0 20px; color: #637067; font-size: 10px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
.eyebrow span { width: 3px; height: 3px; border-radius: 50%; background: #84937e; }
.title { margin: 0; color: #172b20; font-family: var(--font-display), var(--font-sans), sans-serif; font-size: clamp(28px, 3vw, 38px); font-weight: 600; line-height: 1.25; letter-spacing: -.035em; text-transform: none; text-wrap: balance; }
.description { max-width: 340px; margin: 18px 0 30px; color: #637067; font-size: 14px; line-height: 1.75; text-wrap: pretty; }
.actions { display: flex; flex-direction: column; align-items: stretch; max-width: 340px; gap: 10px; }
.primary, .secondary { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; border-radius: 12px; font-family: var(--font-sans), "Helvetica Neue", Arial, sans-serif; font-size: 13px; font-weight: 500; line-height: 1.4; letter-spacing: .01em; text-decoration: none; transition: background-color 160ms ease, color 160ms ease, box-shadow 160ms ease; }
.primary { justify-content: flex-start; gap: 12px; padding: 10px 16px 10px 10px; color: #fff; background: #1d402d; border: 1px solid #183724; box-shadow: 0 4px 10px -6px #173c2866, inset 0 1px 0 #ffffff14; }
.homeIcon { display: grid; place-items: center; width: 32px; height: 32px; flex-shrink: 0; border-radius: 8px; background: #ffffff0d; border: 1px solid #ffffff14; color: #d8e8d8; }
.primary .primaryArrow { margin-left: auto; width: 16px; height: 16px; color: #d8e8d8; }
.primary svg, .secondary svg { width: 18px; height: 18px; flex-shrink: 0; }
.primary:hover { background: #285239; box-shadow: 0 6px 16px -8px #173c2866; }
.secondary { align-self: center; gap: 8px; padding: 10px 14px; color: #526453; background: transparent; }
.secondary svg { width: 15px; height: 15px; }
.secondary:hover { color: #173c28; background: #f4f7f1; }
.primary:active { background: #163923; box-shadow: none; }
.primary:focus-visible, .secondary:focus-visible { outline: 3px solid #729d5e; outline-offset: 4px; }
@media (max-width: 680px) {
  .page { padding: 24px 16px 40px; min-height: auto; }
  .card { grid-template-columns: 1fr; border-radius: 22px; }
  .art { min-height: 190px; }
  .number { font-size: 106px; }
  .orbit { width: 230px; height: 230px; }
  .spark { top: 18%; right: calc(50% - 110px); width: 40px; height: 40px; }
  .content { padding: 32px 24px 36px; text-align: center; }
  .eyebrow { justify-content: center; margin-bottom: 18px; }
  .description { margin: 16px auto 28px; }
  .actions { margin-inline: auto; }
}
@media (prefers-reduced-motion: reduce) {
  .primary, .secondary { transition: none; }
}
